<?php require __DIR__.'/_layout.php';$checks=x1_health_checks();$pass=count(array_filter($checks,fn($x)=>$x['ok']));top(tr('Production Health','Saúde de Produção'));?><section class="card hero"><div class=eyebrow>PRODUCTION GATE</div><div class=kpi><?=$pass?> / <?=count($checks)?> PASS</div><p class=muted><?=tr('This page separates production prerequisites from protocol compatibility.','Esta página separa os requisitos de produção da compatibilidade de protocolo.')?></p></section><section class=section><table><tr><th>Check</th><th>Status</th><th>Detail</th></tr><?php foreach($checks as $x):?><tr><td><?=h($x['name'])?></td><td class="<?=$x['ok']?'good':'warn'?>"><?=$x['ok']?'PASS':'ACTION'?></td><td><?=h($x['detail'])?></td></tr><?php endforeach?></table></section><?php bottom();